import{_ as i,c as a,o,aj as t}from"./chunks/framework.8bp-HAn5.js";const g=JSON.parse('{"title":"物件节点","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"node-object.md","filePath":"node-object.md"}'),r={name:"node-object.md"};function e(n,l,s,u,p,h){return o(),a("div",null,[...l[0]||(l[0]=[t(`<h1 id="物件节点" tabindex="-1">物件节点 <a class="header-anchor" href="#物件节点" aria-label="Permalink to “物件节点”">​</a></h1><pre><code>物体节点通常是和Cocos产生关联的节点，用于操作Cocos中的对象属性
</code></pre><h2 id="动画" tabindex="-1">动画 <a class="header-anchor" href="#动画" aria-label="Permalink to “动画”">​</a></h2><h3 id="骨骼动画" tabindex="-1">骨骼动画 <a class="header-anchor" href="#骨骼动画" aria-label="Permalink to “骨骼动画”">​</a></h3><p>控制Spine骨骼动画的播放，包括切换皮肤、播放动画、设置循环等。</p><p><strong>输入：</strong></p><ul><li>物体：Spine类型的物体节点</li><li>播放：触发播放动画的事件</li></ul><p><strong>输出：</strong></p><ul><li>结束：动画播放结束时触发的事件</li><li>点击：物体被点击时触发的事件</li></ul><p><strong>属性：</strong></p><ul><li>更新模式：选择&quot;全设置&quot;、&quot;仅设置皮肤&quot;或&quot;仅设置动画&quot;</li><li>选择皮肤：要切换的皮肤名称</li><li>选择动画：要播放的动画名称</li><li>是否循环：动画是否循环播放</li><li>播放速率：动画播放的速度倍数（0-10）</li><li>是否自动播放：启动时是否自动播放</li><li>点击等待动画结束：是否等待动画结束后才能点击</li><li>柔和过度：切换动画时是否使用柔和过渡效果</li><li>取消其他触摸事件：播放时是否取消其他触摸事件</li><li>动画结束后响应点击：是否在动画结束后才响应点击</li><li>结束触发次数：动画结束事件触发的次数</li><li>点击重播动画：点击时是否重新播放动画</li><li>点击时间间隔：两次点击之间的最小时间间隔（秒）</li><li>可点击时显示描边：可点击时是否显示描边提示</li><li>是否可点击：物体是否可以响应点击</li><li>触摸提示：关联的触摸提示节点</li><li>触摸提示只出现一次：触摸提示是否只显示一次</li><li>关联动画音频：是否监听动画中的音频事件</li><li>音效：播放时播放的音效</li></ul><p><strong>说明：</strong></p><ul><li>节点会自动从连接的物体获取可用的皮肤和动画列表</li><li>如果物体只有一个动画，可以点击&quot;创建点击彩蛋交互&quot;自动创建交互逻辑</li><li>支持预览动画功能</li></ul><h3 id="数值动画" tabindex="-1">数值动画 <a class="header-anchor" href="#数值动画" aria-label="Permalink to “数值动画”">​</a></h3><p>控制物体属性的数值变化动画，如位置、缩放、透明度等。</p><p><strong>输入：</strong></p><ul><li>物体：要动画的物体节点</li><li>播放：触发播放动画的事件</li></ul><p><strong>输出：</strong></p><ul><li>结束：动画播放结束时触发的事件</li><li>点击：物体被点击时触发的事件</li></ul><p><strong>属性：</strong></p><ul><li>动画时长：动画持续的时间（秒）</li><li>延迟播放时间：延迟多久后开始播放（秒）</li><li>缓动效果：动画的缓动类型（无、淡入、淡出、淡入淡出、回弹、弹跳）</li><li>动画模式：选择&quot;变化目标值&quot;或&quot;变化多少值&quot; <ul><li>变化目标值：将属性变化到指定的目标值</li><li>变化多少值：在现有值基础上增加或减少指定值</li></ul></li><li>无动画直接修改值：是否不使用动画，直接修改值</li><li>取消其他触摸事件：播放时是否取消其他触摸事件</li><li>打断其它数值动画：是否停止物体上正在播放的其他数值动画</li><li>是否自动播放：启动时是否自动播放</li><li>坐标-x/y：目标x/y坐标或变化量</li><li>缩放-x/y：目标缩放值或变化量</li><li>透明度：目标透明度值或变化量（0-255）</li><li>角度：目标角度值或变化量（度）</li><li>锚点x/y：目标锚点值或变化量（-1到1）</li><li>宽度/高度：目标尺寸或变化量</li><li>物体颜色：目标颜色值</li><li>镜头缩放：镜头缩放比例（仅对镜头节点有效）</li></ul><p><strong>说明：</strong></p><ul><li>可以点击&quot;同步目标物体属性&quot;将物体的当前属性同步到动画节点</li><li>可以点击&quot;重置变化多少值&quot;将所有变化量重置为0</li><li>支持预览动画功能</li></ul><h3 id="路径动画" tabindex="-1">路径动画 <a class="header-anchor" href="#路径动画" aria-label="Permalink to “路径动画”">​</a></h3><p>控制物体沿着贝塞尔曲线路径移动。</p><p><strong>输入：</strong></p><ul><li>物体：要移动的物体节点</li><li>长度：移动的长度（动画模式为&quot;随长度&quot;时使用）</li><li>播放：触发播放动画的事件</li><li>重置位置：重置物体到起始位置的事件</li></ul><p><strong>输出：</strong></p><ul><li>结束：动画播放结束时触发的事件</li></ul><p><strong>属性：</strong></p><ul><li>曲线控制点：贝塞尔曲线的控制点坐标数组</li><li>选择控制点：当前选中的控制点索引（-1表示不选中）</li><li>起始位置：路径上的起始位置（0-1）</li><li>终点位置：路径上的终点位置（0-1）</li><li>动画模式：选择&quot;随步长&quot;、&quot;随时间&quot;或&quot;随长度&quot; <ul><li>随步长：每次输入根据步长增加移动位置的百分比</li><li>随时间：输入后自动根据时间从起始位置运行到终点位置</li><li>随长度：根据输入的数值移动对应长度</li></ul></li><li>动画时长：动画持续的时间（秒，仅&quot;随时间&quot;模式）</li><li>动画步长：每次移动的步长（仅&quot;随步长&quot;模式）</li><li>角度跟随路径：移动时物体角度是否跟随路径方向</li><li>开始运行时重置：开始运行时是否重置到起始位置</li><li>是否自动播放：启动时是否自动播放</li></ul><p><strong>说明：</strong></p><ul><li>可以添加、删除控制点来编辑曲线</li><li>支持预览动画功能</li><li>曲线长度会自动计算</li></ul><h2 id="物体成组" tabindex="-1">物体成组 <a class="header-anchor" href="#物体成组" aria-label="Permalink to “物体成组”">​</a></h2><h3 id="连接零件" tabindex="-1">连接零件 <a class="header-anchor" href="#连接零件" aria-label="Permalink to “连接零件”">​</a></h3><p>将一个物体设置为另一个物体的子物体，实现父子关系。</p><p><strong>输入：</strong></p><ul><li>关联父物体：作为父物体的节点</li><li>关联子物体：作为子物体的节点（可动态添加多个）</li></ul><p><strong>说明：</strong></p><ul><li>子物体会跟随父物体移动、旋转、缩放</li><li>可以连接多个子物体到一个父物体</li><li>断开连接时，子物体会自动回到根节点</li></ul><h2 id="传感器" tabindex="-1">传感器 <a class="header-anchor" href="#传感器" aria-label="Permalink to “传感器”">​</a></h2><h3 id="接触感应器" tabindex="-1">接触感应器 <a class="header-anchor" href="#接触感应器" aria-label="Permalink to “接触感应器”">​</a></h3><p>检测两个物体是否发生碰撞接触。</p><p><strong>说明：</strong> 需要配合物体的碰撞框设置使用，当两个物体的碰撞框重叠时触发。</p><h3 id="位置感应器" tabindex="-1">位置感应器 <a class="header-anchor" href="#位置感应器" aria-label="Permalink to “位置感应器”">​</a></h3><p>检测物体是否到达指定位置。</p><p><strong>说明：</strong> 可以检测物体的x、y坐标是否在指定范围内。</p><h3 id="属性感应器" tabindex="-1">属性感应器 <a class="header-anchor" href="#属性感应器" aria-label="Permalink to “属性感应器”">​</a></h3><p>检测物体的某个属性是否满足条件。</p><p><strong>说明：</strong> 可以检测物体的透明度、缩放、角度等属性是否达到指定值。</p><h2 id="物体" tabindex="-1">物体 <a class="header-anchor" href="#物体" aria-label="Permalink to “物体”">​</a></h2><p>创建和管理Cocos Creator中的物体节点。</p><p><strong>输出：</strong></p><ul><li>物体：创建的物体节点（类型为codeNode）</li></ul><p><strong>属性：</strong></p><ul><li>是否作为UI：是否将物体作为UI元素</li><li>物体类型：选择物体类型（空物体、图片、文本、spine等）</li><li>资源：物体使用的资源路径</li><li>加载时机：选择&quot;初始化时&quot;或&quot;输入时&quot;</li><li>是否预乘：是否使用预乘Alpha</li><li>层级：物体的zIndex层级</li><li>以y轴动态计算层级：是否根据y坐标自动计算层级</li><li>坐标-x/y：物体的位置坐标</li><li>缩放-x/y：物体的缩放比例</li><li>透明度：物体的透明度（0-255）</li><li>角度：物体的旋转角度（度）</li><li>锚点x/y：物体的锚点位置（-1到1）</li><li>宽度/高度：物体的尺寸</li><li>物体颜色：物体的颜色（十六进制）</li><li>文本：文本内容（仅文本类型）</li><li>描边宽度：文本描边宽度（仅文本类型）</li><li>描边颜色：文本描边颜色（仅文本类型）</li></ul><p><strong>说明：</strong></p><ul><li>物体节点包含一个特殊的codeNode输出接口，需要与接受codeNode输入的节点连接</li><li>如果没有连接codeNode输出，相关节点可能无法响应触摸事件或获取实体对象</li><li>可以右键点击节点选择&quot;编辑碰撞框&quot;来设置碰撞检测区域</li><li>节点会根据资源类型自动显示预览图</li></ul><h2 id="字幕组" tabindex="-1">字幕组 <a class="header-anchor" href="#字幕组" aria-label="Permalink to “字幕组”">​</a></h2><p>快速创建和管理绘本中的浮动字幕。</p><p><strong>输入：</strong></p><ul><li>物体：作为字幕容器的物体节点</li></ul><p><strong>输出：</strong></p><ul><li>列表：字幕文本列表（数组）</li></ul><p><strong>属性：</strong></p><ul><li>用作底部字幕：是否作为页面底部的通用字幕</li><li>竖向文本：文本是否竖向排列</li><li>排列：文本的对齐方式（居左/下、居中、居右/上）</li><li>首行缩进：首行的缩进距离</li><li>行距：行与行之间的间距</li><li>字号：字体大小</li><li>颜色：文字颜色</li><li>描边宽度：文字描边宽度</li><li>描边颜色：文字描边颜色</li><li>运行前隐藏：是否在运行前隐藏字幕</li><li>运行结束隐藏：是否在运行结束后隐藏字幕</li><li>隐藏底层文字：是否隐藏底层的基础文字</li><li>是否颜色过渡：是否使用颜色过渡动画</li><li>过渡颜色：颜色过渡的目标颜色</li></ul><p><strong>说明：</strong></p><ul><li>可以点击&quot;添加一行&quot;和&quot;删除一行&quot;来管理字幕行数</li><li>每行字幕可以单独设置文本内容</li><li>支持自动识别音频生成字幕（需要配置讯飞接口）</li></ul><h2 id="镜头" tabindex="-1">镜头 <a class="header-anchor" href="#镜头" aria-label="Permalink to “镜头”">​</a></h2><p>在绘本中使用镜头位移和缩放效果。</p><p><strong>输出：</strong></p><ul><li>物体：镜头节点（类型为codeNode）</li></ul><p><strong>属性：</strong></p><ul><li>坐标-x/y：镜头的位置坐标</li><li>镜头缩放：镜头的缩放比例（1-10）</li></ul><p><strong>说明：</strong></p><ul><li>镜头节点会创建一个Camera组件</li><li>可以控制整个场景的视角和缩放</li><li>支持预览模式显示镜头范围</li><li>可以点击&quot;重置到默认状态&quot;恢复初始设置</li></ul><h2 id="整体移动" tabindex="-1">整体移动 <a class="header-anchor" href="#整体移动" aria-label="Permalink to “整体移动”">​</a></h2><p>用于在开发时整体移动所有物体，方便调整布局。</p><p><strong>属性：</strong></p><ul><li>坐标-x：所有物体x坐标的变化量</li><li>坐标-y：所有物体y坐标的变化量</li></ul><p><strong>说明：</strong></p><ul><li>修改坐标值后，所有物体节点会同步移动相同的距离</li><li>主要用于开发阶段的快速布局调整</li></ul><h2 id="分镜预览缩放" tabindex="-1">分镜预览缩放 <a class="header-anchor" href="#分镜预览缩放" aria-label="Permalink to “分镜预览缩放”">​</a></h2><p>用于在开发时分镜预览缩放，以便看清超出屏幕范围的物体。</p><p><strong>属性：</strong></p><ul><li>位移x：预览区域的x轴偏移</li><li>位移y：预览区域的y轴偏移</li><li>缩放：预览区域的缩放比例（0.25-1）</li></ul><p><strong>说明：</strong></p><ul><li>仅影响编辑器的预览显示，不影响实际运行效果</li><li>可以调整预览区域的位置和缩放，方便查看大场景</li><li>可以点击&quot;重置到默认状态&quot;恢复初始设置</li></ul>`,88)])])}const c=i(r,[["render",e]]);export{g as __pageData,c as default};
